#include <Arduino.h>
#include "driver/gpio.h"
#include "usb/usb_host.h"
#include "hid_host.h"

static const char *TAG = "USB_HOST_TEST";

QueueHandle_t hid_host_event_queue;

typedef struct {
  hid_host_device_handle_t hid_device_handle;
  hid_host_driver_event_t event;
  void *arg;
} hid_host_event_queue_t;

void hid_host_interface_callback(
    hid_host_device_handle_t hid_device_handle,
    const hid_host_interface_event_t event,
    void *arg)
{
  uint8_t data[64] = {0};
  size_t data_length = 0;

  switch (event) {

    case HID_HOST_INTERFACE_EVENT_INPUT_REPORT:

      if (hid_host_device_get_raw_input_report_data(
            hid_device_handle,
            data,
            sizeof(data),
            &data_length) == ESP_OK) {

        Serial0.print("HID REPORT [");
        Serial0.print(data_length);
        Serial0.print("]: ");

        for (size_t i = 0; i < data_length; i++) {
          if (data[i] < 0x10) Serial0.print("0");
          Serial0.print(data[i], HEX);
          Serial0.print(" ");
        }

        Serial0.println();
      }

      break;

    case HID_HOST_INTERFACE_EVENT_DISCONNECTED:
      Serial0.println("HID DEVICE DISCONNECTED");
      hid_host_device_close(hid_device_handle);
      break;

    default:
      break;
  }
}

void hid_host_device_callback(
    hid_host_device_handle_t hid_device_handle,
    const hid_host_driver_event_t event,
    void *arg)
{
  hid_host_event_queue_t evt;

  evt.hid_device_handle = hid_device_handle;
  evt.event = event;
  evt.arg = arg;

  xQueueSend(hid_host_event_queue, &evt, 0);
}

void usb_host_task(void *arg)
{
  usb_host_config_t host_config = {
    .skip_phy_setup = false,
    .intr_flags = ESP_INTR_FLAG_LEVEL1
  };

  Serial0.println("Installing USB Host...");

  esp_err_t err = usb_host_install(&host_config);

  if (err != ESP_OK) {
    Serial0.print("USB Host install FAILED: ");
    Serial0.println(esp_err_to_name(err));
    vTaskDelete(NULL);
    return;
  }

  Serial0.println("USB Host installed OK");

  while (true) {
    uint32_t event_flags;

    usb_host_lib_handle_events(
      portMAX_DELAY,
      &event_flags
    );

    if (event_flags & USB_HOST_LIB_EVENT_FLAGS_NO_CLIENTS) {
      usb_host_device_free_all();
    }
  }
}

void hid_host_task(void *arg)
{
  hid_host_event_queue = xQueueCreate(
    10,
    sizeof(hid_host_event_queue_t)
  );

  hid_host_driver_config_t config = {
    .create_background_task = true,
    .task_priority = 5,
    .stack_size = 4096,
    .core_id = 0,
    .callback = hid_host_device_callback,
    .callback_arg = NULL
  };

  Serial0.println("Installing HID Host...");

  esp_err_t err = hid_host_install(&config);

  if (err != ESP_OK) {
    Serial0.print("HID Host install FAILED: ");
    Serial0.println(esp_err_to_name(err));
    vTaskDelete(NULL);
    return;
  }

  Serial0.println("HID Host installed OK");

  hid_host_event_queue_t evt;

  while (true) {

    if (xQueueReceive(
          hid_host_event_queue,
          &evt,
          portMAX_DELAY)) {

      if (evt.event == HID_HOST_DRIVER_EVENT_CONNECTED) {

        Serial0.println("HID DEVICE CONNECTED!");

        hid_host_dev_params_t params;

        if (hid_host_device_get_params(
              evt.hid_device_handle,
              &params) == ESP_OK) {

          Serial0.print("VID: 0x");
          Serial0.println(params.vid, HEX);

          Serial0.print("PID: 0x");
          Serial0.println(params.pid, HEX);
        }

        hid_host_device_config_t dev_config = {
          .callback = hid_host_interface_callback,
          .callback_arg = NULL
        };

        if (hid_host_device_open(
              evt.hid_device_handle,
              &dev_config) == ESP_OK) {

          hid_host_device_start(evt.hid_device_handle);

          Serial0.println("HID DEVICE STARTED");
        }
      }
    }
  }
}

void setup()
{
  Serial0.begin(115200);
  delay(2000);

  Serial0.println();
  Serial0.println("================================");
  Serial0.println("ESP32-S3 USB HOST HID TEST");
  Serial0.println("================================");

  xTaskCreatePinnedToCore(
    usb_host_task,
    "usb_host",
    4096,
    NULL,
    2,
    NULL,
    0
  );

  delay(100);

  xTaskCreatePinnedToCore(
    hid_host_task,
    "hid_host",
    4096,
    NULL,
    3,
    NULL,
    0
  );
}

void loop()
{
  delay(1000);
}
